use rhwp::{DocumentCore,renderer::{TextStyle,layout::{EmbeddedTextMeasurer,TextMeasurer}}};
use serde_json::{Value,json};
use sha2::{Sha256,Digest};
use std::{path::PathBuf,collections::BTreeMap};
fn repo()->PathBuf{PathBuf::from(std::env::var("JUEONY_REPO").unwrap())}
fn sha(b:&[u8])->String{Sha256::digest(b).iter().map(|b|format!("{b:02x}")).collect()}
fn write(name:&str,value:Value){let folder=repo().join("build/gulimche-admission-candidate81").join(std::env::var("JUEONY_PHASE").unwrap());std::fs::create_dir_all(&folder).unwrap();std::fs::write(folder.join(format!("{name}.json")),serde_json::to_vec_pretty(&value).unwrap()).unwrap();}
fn oracle()->Value{serde_json::from_slice(&std::fs::read(repo().join("build/gulimche-admission-candidate81/independent-admission-oracle.json")).unwrap()).unwrap()}
fn load(item:&Value,actual:bool)->DocumentCore{let k=if actual{"hancom"}else{"source"};let bytes=std::fs::read(repo().join(item[k].as_str().unwrap())).unwrap();assert_eq!(sha(&bytes),item[format!("{k}SHA256")].as_str().unwrap());DocumentCore::from_bytes(&bytes).unwrap()}
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|page|json!({"page":page,"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(page).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(page).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn safe(v:&Value)->Value{match v{Value::Null|Value::Number(_)|Value::Bool(_)=>v.clone(),Value::String(s)=>json!({"characters":s.chars().count(),"sha256":sha(s.as_bytes())}),_=>json!({"sha256":sha(&serde_json::to_vec(v).unwrap())})}}
fn diff(a:&Value,b:&Value,p:&str,out:&mut Vec<Value>){match(a,b){(Value::Number(a),Value::Number(b))=>{let(x,y)=(a.as_f64().unwrap(),b.as_f64().unwrap());if !x.is_finite()||!y.is_finite()||(x-y).abs()>0.2{out.push(json!({"path":p,"before":a,"after":b}));}},(Value::Array(a),Value::Array(b))=>{for i in 0..a.len().max(b.len()){diff(a.get(i).unwrap_or(&Value::Null),b.get(i).unwrap_or(&Value::Null),&format!("{p}/{i}"),out);}},(Value::Object(a),Value::Object(b))=>{let keys:std::collections::BTreeSet<_>=a.keys().chain(b.keys()).collect();for k in keys{diff(a.get(k).unwrap_or(&Value::Null),b.get(k).unwrap_or(&Value::Null),&format!("{p}/{k}"),out);}},_=>if a!=b{out.push(json!({"path":p,"before":safe(a),"after":safe(b)}));}}}
fn layout_equal(a:&Value,b:&Value,label:&str){let mut delta=vec![];diff(a,b,"pages",&mut delta);assert!(delta.is_empty(),"{label}: {} full geometry differences; {:?}",delta.len(),delta.iter().take(4).collect::<Vec<_>>());}
fn body(d:&DocumentCore)->String{sha(&serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap())}
fn metadata(d:&DocumentCore)->Value{serde_json::from_str::<Value>(&d.get_document_metadata_native()).unwrap()["values"].clone()}
fn checked(d:&DocumentCore,hwpx:bool)->Vec<u8>{let old=body(d);let r=if hwpx{d.export_hwpx_native_with_report().unwrap()}else{d.export_hwp_with_adapter_snapshot_with_report().unwrap()};assert!(r.content_loss().is_empty(),"{}",r.content_loss().to_json());let bytes=r.into_bytes();assert_eq!(old,body(d));assert_eq!(metadata(d),metadata(&DocumentCore::from_bytes(&bytes).unwrap()));bytes}
fn starts(d:&DocumentCore,owner:usize)->Vec<usize>{let mut rows=BTreeMap::<(usize,i64),usize>::new();for page in 0..d.page_count(){let layout:Value=serde_json::from_str(&d.get_page_text_layout_native(page).unwrap()).unwrap();for r in layout["runs"].as_array().unwrap(){if r["parentParaIdx"].as_u64()==Some(owner as u64)&&r["cellIdx"].as_u64()==Some(0)&&r["paraIdx"].as_u64()==Some(0){let key=(page as usize,(r["y"].as_f64().unwrap()*10.0).round() as i64);let start=r["charStart"].as_u64().unwrap() as usize;rows.entry(key).and_modify(|v|*v=(*v).min(start)).or_insert(start);}}}rows.into_values().collect()}

#[test]fn guli_own68_independent_native_admission_boundaries(){
 let mut observations=vec![];let mut failures=vec![];let data=oracle();
 for item in data.as_array().unwrap(){for actual in[false,true]{let d=load(item,actual);let old=body(&d);for expected in item["expected"].as_array().unwrap(){let owner=expected["tableIndex"].as_u64().unwrap() as usize;let got=starts(&d,owner);let wanted=expected["lineStarts"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as usize).collect::<Vec<_>>();if got!=wanted{failures.push(json!({"file":item["source"],"actualInput":actual,"table":owner,"expected":wanted,"actual":got}));}observations.push(json!({"file":item["source"],"actualInput":actual,"table":owner,"lineStarts":got}));}assert_eq!(old,body(&d));}}
 write("admission68",json!({"independentRawNativeTables":68,"sourcesIncludingActual":136,"observations":observations,"failures":failures,"rawOracleUnchanged":true}));assert!(failures.is_empty(),"{} native admission mismatches; {:?}",failures.len(),failures.iter().take(8).collect::<Vec<_>>());
}

fn style(height:i32,ratio:i32)->TextStyle{TextStyle{font_family:"굴림체".into(),font_size:height as f64/75.0,ratio:ratio as f64/100.0,font_metric_trusted:true,..Default::default()}}
fn measure(c:char,s:&TextStyle)->f64{EmbeddedTextMeasurer.compute_char_positions(&c.to_string(),s)[1]*75.0}
#[test]fn guli_shared_measured_glyph_decisions(){
 let mut observations=vec![];
 for (height,ratio,full,space,ascii) in[(900,100,900.,448.,452.),(1000,97,968.,484.,484.),(1100,100,1100.,548.,552.),(1100,97,1064.,532.,532.),(1200,100,1200.,600.,600.)]{let s=style(height,ratio);for(c,want)in[('가',full),('나',full),(' ',space),('.',ascii),('i',ascii),('W',ascii)]{let got=measure(c,&s);observations.push(json!({"heightHU":height,"ratio":ratio,"unicode":format!("U+{:04X}",c as u32),"expectedHU":want,"actualHU":got}));assert!((got-want).abs()<1e-8,"{height}/{ratio}/{c}: {got} vs{want}");}}
 write("glyph-decisions",json!({"cases":30,"observations":observations,"oracle":"Actual Hancom 36+32 table thresholds, original prediction failures preserved separately"}));
}

#[test]fn guli_excluded_measurement_contexts(){
 let s=style(1100,97);let mut contexts=vec![];
 for key in["untrusted","bold","italic","kerning","superscript","subscript","hft","hft-dot","font-space","tracking","other-face","unknown-face","fractional-ratio","fractional-size"]{let mut n=s.clone();match key{"untrusted"=>n.font_metric_trusted=false,"bold"=>n.bold=true,"italic"=>n.italic=true,"kerning"=>n.kerning=true,"superscript"=>n.superscript=true,"subscript"=>n.subscript=true,"hft"=>n.hft_hangul_face=true,"hft-dot"=>n.hft_fullwidth_dot=true,"font-space"=>n.font_space_em=Some(0.5),"tracking"=>n.letter_spacing=0.2,"other-face"=>n.font_family="바탕체".into(),"unknown-face"=>n.font_family="JUEONY UNKNOWN FONT".into(),"fractional-ratio"=>n.ratio=0.97001,"fractional-size"=>n.font_size=1018.5/75.0,_=>unreachable!()};contexts.push(json!({"case":key,"values":[measure('가',&n),measure(' ',&n),measure('.',&n),measure('i',&n),measure('W',&n)]}));}
 let unicode=['\u{00A0}','\u{2007}','\u{2018}','\u{2019}','\u{318D}','\u{3000}','\u{4E00}'];for c in unicode{contexts.push(json!({"case":format!("unicode-U+{:04X}",c as u32),"values":[measure(c,&s)]}));}
 write("excluded-contexts",json!({"cases":contexts,"scope":"Must compare unchanged formal81 with candidate values; no new success claim for excluded contexts"}));
}

#[test]fn guli_own68_both_formats_two_cycles(){
 let data=oracle();let mut observations=vec![];
 for item in data.as_array().unwrap(){for actual in[false,true]{let d=load(item,actual);let before=state(&d);for hwpx in[false,true]{let b=checked(&d,hwpx);let r=DocumentCore::from_bytes(&b).unwrap();let after=state(&r);let mut delta=vec![];diff(&before,&after,"pages",&mut delta);observations.push(json!({"source":item["source"],"actualInput":actual,"hwpx":hwpx,"cycle":1,"differences":delta.len(),"first":delta.iter().take(8).collect::<Vec<_>>(),"sha256":sha(&b)}));write("own68-save-cycles",json!({"observations":observations}));layout_equal(&before,&after,"matrix first save");let b=checked(&r,hwpx);let twice=DocumentCore::from_bytes(&b).unwrap();layout_equal(&before,&state(&twice),"matrix second save");observations.push(json!({"source":item["source"],"actualInput":actual,"hwpx":hwpx,"cycle":2,"differences":0,"sha256":sha(&b)}));}layout_equal(&before,&state(&d),"live unchanged");}}
 write("own68-save-cycles",json!({"strictGeometryReopens":16,"observations":observations,"metadata5Exact":true,"nativeLossEmpty":true}));
}

#[test]fn guli_real_cell_edit_snapshot_history(){
 let item=&oracle()[0];let mut d=load(item,false);let original=state(&d);let original_body=body(&d);let undo=d.save_snapshot_native();let table=&d.document().sections[0].paragraphs[0].controls[0];let length=match table{rhwp::model::control::Control::Table(t)=>t.cells[0].paragraphs[0].text.encode_utf16().count(),_=>{let t=d.document().sections[0].paragraphs[0].controls.iter().find_map(|c|match c{rhwp::model::control::Control::Table(t)=>Some(t),_=>None}).unwrap();t.cells[0].paragraphs[0].text.encode_utf16().count()}};
 let ci=d.document().sections[0].paragraphs[0].controls.iter().position(|c|matches!(c,rhwp::model::control::Control::Table(_))).unwrap();d.insert_text_in_cell_native(0,0,ci,0,0,length,"나").unwrap();let edited=state(&d);let changed_body=body(&d);assert_ne!(original_body,changed_body);let redo=d.save_snapshot_native();d.restore_snapshot_native(undo).unwrap();layout_equal(&original,&state(&d),"undo");assert_eq!(body(&d),original_body);d.restore_snapshot_native(redo).unwrap();layout_equal(&edited,&state(&d),"redo");assert_eq!(body(&d),changed_body);
 for hwpx in[false,true]{let b=checked(&d,hwpx);let r=DocumentCore::from_bytes(&b).unwrap();layout_equal(&edited,&state(&r),"real edit first save");let b=checked(&r,hwpx);let r=DocumentCore::from_bytes(&b).unwrap();layout_equal(&edited,&state(&r),"real edit second save");}
 write("real-history",json!({"realCellTextEdit":true,"undo":true,"redo":true,"strictGeometryReopens":4,"metadata5Exact":true}));
}

#[test]fn guli_public_readonly_numeric_proxy(){
 let mut rows=vec![];
 for (label,left,right) in [
 ("mcst-original-to-actual","build/hancom-final-file-review-20261017/source-mcst-bid-2026.hwp","build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx"),
 ("mcst-historical-to-actual","build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx.hwpx","build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx"),
 ("python3-direct-to-actual","build/hancom-final-file-review-20261017/source-python-hwpx-3.hwpx","build/hancom-final-file-review-20261017/python-hwpx-3-hwp-hancom.hwp"),
 ("python3-unclaimed-diagnostic-to-actual","build/file-closure69-public/python3-diagnostic-unclaimed-origin.hwp","build/hancom-final-file-review-20261017/python-hwpx-3-hwp-hancom.hwp")]{
 let a=std::fs::read(repo().join(left)).unwrap();let b=std::fs::read(repo().join(right)).unwrap();let d=DocumentCore::from_bytes(&a).unwrap();let r=DocumentCore::from_bytes(&b).unwrap();let model=body(&d);let expected_model=body(&r);let before=state(&d);let after=state(&r);let mut delta=vec![];diff(&before,&after,"pages",&mut delta);let mut fields=BTreeMap::<String,usize>::new();for x in &delta{let p=x["path"].as_str().unwrap();let field=if p.contains("/charX/"){"charX"}else{p.rsplit('/').next().unwrap()};*fields.entry(field.into()).or_default()+=1;}
 let operands=|v:&Value|v.as_array().unwrap().iter().flat_map(|page|page["text"]["runs"].as_array().unwrap().iter().filter(|run|run["parentParaIdx"]==100&&((run["cellIdx"]==0&&run["paraIdx"]==1)||(run["cellIdx"]==2&&run["paraIdx"]==0))).map(|run|json!({"page":page["page"],"cell":run["cellIdx"],"paragraph":run["paraIdx"],"charStart":run["charStart"],"textLength":run["text"].as_str().map(|s|s.chars().count()),"textSHA256":run["text"].as_str().map(|s|sha(s.as_bytes())),"font":run["fontFamily"],"fontSize":run["fontSize"],"ratio":run["ratio"],"x":run["x"],"y":run["y"],"w":run["w"],"h":run["h"],"charX":run["charX"]}))).collect::<Vec<_>>();
 rows.push(json!({"axis":label,"input":left,"inputSHA256":sha(&a),"hancom":right,"hancomSHA256":sha(&b),"sourcePages":d.page_count(),"hancomPages":r.page_count(),"geometryDifferences":delta.len(),"geometryFields":fields,"firstDifferences":delta.iter().take(12).collect::<Vec<_>>(),"targetOperands":{"source":operands(&before),"hancom":operands(&after)}}));assert_eq!(model,body(&d));assert_eq!(expected_model,body(&r));assert_eq!(sha(&a),sha(&std::fs::read(repo().join(left)).unwrap()));assert_eq!(sha(&b),sha(&std::fs::read(repo().join(right)).unwrap()));
 }
 write("public-numeric-proxy",json!({"rows":rows,"scope":"Read-only Native proxy; full published fields including raw IDs and 0.2 comparison. Text hashed; no public document bytes or full snapshots written. Counts do not claim compatibility completion.","originalsUnchanged":true}));
}

#[test]fn guli_public_font_ownership_readonly(){
 let mut output=vec![];
 for name in ["build/hancom-final-file-review-20261017/source-python-hwpx-3.hwpx","build/hancom-final-file-review-20261017/python-hwpx-3-hwp-hancom.hwp","build/file-closure69-public/python3-diagnostic-unclaimed-origin.hwp"]{
 let bytes=std::fs::read(repo().join(name)).unwrap();let d=DocumentCore::from_bytes(&bytes).unwrap();let before=body(&d);let doc=d.document();let p=&doc.sections[0].paragraphs[100];let table=p.controls.iter().find_map(|c|match c{rhwp::model::control::Control::Table(t)=>Some(t),_=>None}).unwrap();let mut records=vec![];
 for (cell,paragraph) in [(0,1),(2,0)]{let para=&table.cells[cell].paragraphs[paragraph];for r in &para.char_shapes{let cs=&doc.doc_info.char_shapes[r.char_shape_id as usize];let resolved=rhwp::renderer::style_resolver::resolve_styles(&doc.doc_info,96.0);let rs=&resolved.char_styles[r.char_shape_id as usize];let fonts=cs.font_ids.iter().enumerate().map(|(lang,&id)|{let f=doc.doc_info.font_faces.get(lang).and_then(|v|v.get(id as usize));json!({"language":lang,"id":id,"font":f.map(|f|json!({"name":f.name,"type":f.alt_type,"altName":f.alt_name,"defaultName":f.default_name,"substitute":f.subst_font,"embedded":f.is_embedded,"rawSHA256":f.raw_data.as_ref().map(|b|sha(b))}))})}).collect::<Vec<_>>();records.push(json!({"cell":cell,"paragraph":paragraph,"characterShape":r.char_shape_id,"baseSize":cs.base_size,"resolved":{"fontFamilies":rs.font_families,"trusted":rs.font_families_metric_trusted,"fontSizes":rs.font_sizes,"ratios":rs.ratios,"hftHangul":rs.font_families_hft_hangul,"hftDot":rs.font_families_hft_fullwidth_dot,"metricFaces":rs.font_families_metric_face,"fontSpaceEm":rs.font_space_em,"bold":rs.bold,"italic":rs.italic,"kerning":rs.kerning,"superscript":rs.superscript,"subscript":rs.subscript},"fontIDs":cs.font_ids,"ratios":cs.ratios,"relativeSizes":cs.relative_sizes,"spacings":cs.spacings,"bold":cs.bold,"italic":cs.italic,"kerning":cs.kerning,"fontSpace":cs.use_font_space,"fonts":fonts}));}}
 output.push(json!({"file":name,"sha256":sha(&bytes),"records":records}));assert_eq!(before,body(&d));assert_eq!(sha(&bytes),sha(&std::fs::read(repo().join(name)).unwrap()));
 }
 write("public-font-ownership",json!({"observations":output,"rawFontDefinitionsOnly":true,"noSubstitutionOrTypeRewrite":true}));
}

#[test]fn guli_owned_exclusions_baseline_contract(){
 fn fonts(d:&DocumentCore)->Value{json!(d.document().doc_info.font_faces.iter().enumerate().flat_map(|(language,list)|list.iter().enumerate().filter(|(_,f)|f.name=="굴림체").map(move |(id,f)|json!({"language":language,"id":id,"type":f.alt_type,"embedded":f.is_embedded,"binaryReference":f.bin_item_id_ref}))).collect::<Vec<_>>())}

 let cases:Value=serde_json::from_slice(&std::fs::read(repo().join("build/gulimche-admission-candidate81/owned-exclusions-v5.json")).unwrap()).unwrap();let mut rows=vec![];
 for item in cases.as_array().unwrap(){let bytes=std::fs::read(repo().join(item["file"].as_str().unwrap())).unwrap();assert_eq!(sha(&bytes),item["sha256"].as_str().unwrap());let d=DocumentCore::from_bytes(&bytes).unwrap();let model=body(&d);let doc_info=sha(format!("{:?}",d.document().doc_info).as_bytes());let current=state(&d);let mut artifacts=vec![];
 for hwpx in [false,true]{let report=if hwpx{d.export_hwpx_native_with_report().unwrap()}else{d.export_hwp_with_adapter_snapshot_with_report().unwrap()};let loss=report.content_loss().to_json();let saved=report.into_bytes();let reopened=DocumentCore::from_bytes(&saved).unwrap();let mut delta=vec![];diff(&current,&state(&reopened),"pages",&mut delta);artifacts.push(json!({"hwpx":hwpx,"bytesSHA256":sha(&saved),"lossSHA256":sha(loss.as_bytes()),"layout":state(&reopened),"layoutSHA256":sha(&serde_json::to_vec(&state(&reopened)).unwrap()),"geometryDifferences":delta.len(),"metadata":metadata(&reopened),"fontOwnership":fonts(&reopened)}));assert_eq!(model,body(&d));assert_eq!(doc_info,sha(format!("{:?}",d.document().doc_info).as_bytes()));}
 rows.push(json!({"case":item["name"],"inputSHA256":sha(&bytes),"paragraphModelSHA256":model,"fontOwnership":fonts(&d),"docInfoModelSHA256":sha(format!("{:?}",d.document().doc_info).as_bytes()),"liveLayout":current,"liveLayoutSHA256":sha(&serde_json::to_vec(&current).unwrap()),"artifacts":artifacts}));assert_eq!(sha(&bytes),sha(&std::fs::read(repo().join(item["file"].as_str().unwrap())).unwrap()));}
 write("owned-exclusions",json!({"rows":rows,"scope":"Compare full baseline83 bytes/model/layout/loss exactly. Existing guarded losses are not reclassified as supported success."}));
}
